''
)
function Get-Art([int]$index) {
    $stream = [IO.MemoryStream]::new([Convert]::FromBase64String($art[$index]))
    try {
        $source = [System.Drawing.Image]::FromStream($stream)
        try { if ($index -eq 0) { return [System.Drawing.Bitmap]::new($source) }
            return [System.Drawing.Bitmap]::new($source, 241, 109) }
        finally { $source.Dispose() }
    } finally { $stream.Dispose() }
}
function Open-Fishing {
    Add-Type -AssemblyName System.Windows.Forms
    Add-Type -AssemblyName System.Drawing
    [System.Windows.Forms.Application]::EnableVisualStyles()
    
    $form = New-Object System.Windows.Forms.Form
    $form.Text = 'NightShift — Рыбалка'
    $form.ClientSize = New-Object System.Drawing.Size(900, 570)
    $form.MinimumSize = $form.Size
    $form.BackColor = [System.Drawing.Color]::FromArgb(18, 19, 24)
    $form.ForeColor = [System.Drawing.Color]::WhiteSmoke
    $form.Font = New-Object System.Drawing.Font('Segoe UI', 11)
    $form.StartPosition = 'CenterParent'
    
    $menu = New-Object System.Windows.Forms.ListBox
    $menu.SetBounds(20, 25, 210, 515)
    $menu.BackColor = [System.Drawing.Color]::FromArgb(34, 35, 43)
    $menu.ForeColor = [System.Drawing.Color]::WhiteSmoke
    $menu.Items.AddRange([object[]]@('Рыбалка','Лесоруб','Карьер','Стройка','Охотник','Фермер','Грибник','Качалка','Швейка','Таксист','Угонщик'))
    $form.Controls.Add($menu)
    
    function Add-Label($text, $x, $y, $width, $height, $size) {
        $label = New-Object System.Windows.Forms.Label
        $label.Text = $text
        $label.SetBounds($x, $y, $width, $height)
        $label.Font = New-Object System.Drawing.Font('Segoe UI', $size)
        $form.Controls.Add($label)
        return $label
    }
    
    $title = Add-Label 'Рыбалка' 260 28 600 65 30
    $status = Add-Label '' 263 125 600 90 18
    $stats = Add-Label '' 263 238 600 50 14
    
    function Add-Button($text, $x, $color) {
        $button = New-Object System.Windows.Forms.Button
        $button.Text = $text
        $button.SetBounds($x, 325, 175, 52)
        $button.FlatStyle = 'Flat'
        $button.BackColor = $color
        $form.Controls.Add($button)
        return $button
    }
    
    $red = [System.Drawing.Color]::FromArgb(159, 20, 55)
    $gray = [System.Drawing.Color]::FromArgb(42, 43, 52)
    $start = Add-Button 'Запустить' 263 $red
    $stop = Add-Button 'Остановить' 454 $gray
    $hook = Add-Button 'Подсечь' 645 $red
    $timer = New-Object System.Windows.Forms.Timer
    $timer.Interval = 100
    $clock = New-Object System.Diagnostics.Stopwatch
    $session = @{ Catch = 0; Due = 0; Biting = $false }
    $random = New-Object Random
    
    function Reset-Cast {
        $session.Biting = $false
        $session.Due = $clock.ElapsedMilliseconds + $random.Next(1800, 5500)
        $hook.Enabled = $false
        $status.Text = 'Ожидание поклёвки…'
    }
    function Stop-Fishing {
        $timer.Stop()
        $clock.Stop()
        $start.Enabled = $true
        $stop.Enabled = $false
        $hook.Enabled = $false
    }
    $timer.Add_Tick({
        $elapsed = $clock.ElapsedMilliseconds
        $stats.Text = 'Улов: {0}     Время: {1:mm\:ss}' -f $session.Catch, $clock.Elapsed
        if ($elapsed -ge $session.Due) {
            if ($session.Biting) {
                Reset-Cast
                $status.Text = 'Рыба сорвалась. Новый заброс…'
            } else {
                $session.Biting = $true
                $session.Due = $elapsed + 1200
                $hook.Enabled = $true
                $status.Text = 'Клюёт! Подсекай.'
            }
        }
    })
    $start.Add_Click({
        $session.Catch = 0
        $clock.Restart()
        Reset-Cast
        $start.Enabled = $false
        $stop.Enabled = $true
        $timer.Start()
    })
    $stop.Add_Click({ Stop-Fishing; $status.Text = 'Тренировка остановлена' })
    $hook.Add_Click({
        if ($timer.Enabled -and $session.Biting -and $clock.ElapsedMilliseconds -lt $session.Due) {
            $session.Catch++
            Reset-Cast
            $status.Text = 'Поймал! Новый заброс…'
        }
    })
    $menu.Add_SelectedIndexChanged({
        Stop-Fishing
        $title.Text = [string]$menu.SelectedItem
        $fishing = $menu.SelectedIndex -eq 0
        $start.Visible = $stop.Visible = $hook.Visible = $stats.Visible = $fishing
        $stats.Text = 'Улов: 0     Время: 00:00'
        if ($fishing) { $status.Text = 'Офлайн-тренажёр. Нажми «Запустить».' }
        else { $status.Text = 'Раздел пока в разработке.' }
    })
    $menu.SelectedIndex = 0
    try { [void]$form.ShowDialog() }
    finally { $timer.Dispose(); $form.Dispose() }
}
$jobs = @('Рыбалка','Лесоруб','Карьер','Стройка','Охотник','Фермер','Грибник','Качалка','Швейка','Таксист','Угонщик')
$window = [System.Windows.Forms.Form]::new()
$window.Text = 'NightShift'
$window.ClientSize = [System.Drawing.Size]::new(1220, 695)
$window.StartPosition = 'CenterScreen'
$window.BackColor = [System.Drawing.Color]::FromArgb(16,17,21)
$window.Font = [System.Drawing.Font]::new('Segoe UI',11)
$window.ForeColor = [System.Drawing.Color]::WhiteSmoke
$window.AutoScroll = $true
$images = [System.Collections.Generic.List[System.Drawing.Image]]::new()
$accent = [System.Drawing.Color]::FromArgb(125,25,46)

function Add-Text($parent, [string]$caption, [int]$x, [int]$y, [int]$w, [int]$h, [int]$size) {
    $label = [System.Windows.Forms.Label]::new()
    $label.Text = $caption
    $label.SetBounds($x,$y,$w,$h)
    $label.Font = [System.Drawing.Font]::new('Segoe UI',$size,[System.Drawing.FontStyle]::Bold)
    $parent.Controls.Add($label)
}
function Select-Job([int]$index) {
    if ($index -eq 0) { Open-Fishing; return }
    [void][System.Windows.Forms.MessageBox]::Show($window,'Раздел пока в разработке.',$jobs[$index])
}
Add-Text $window 'NightShift' 20 28 158 45 20
$hero = [System.Windows.Forms.Panel]::new()
$hero.SetBounds(194,16,1008,176)
$hero.BackgroundImage = Get-Art 0
$images.Add($hero.BackgroundImage)
$hero.BackgroundImageLayout = 'Stretch'
$window.Controls.Add($hero)
Add-Text $hero 'Каталог работ' 24 50 310 58 29
$hero.Controls[0].BackColor = [System.Drawing.Color]::Transparent

for ($index = 0; $index -lt $jobs.Count; $index++) {
    $nav = [System.Windows.Forms.Button]::new()
    $nav.Text = $jobs[$index]
    $nav.Tag = $index
    $nav.SetBounds(16,(84 + $index * 43),158,38)
    $nav.TextAlign = 'MiddleLeft'
    $nav.FlatStyle = 'Flat'
    $nav.FlatAppearance.BorderSize = 0
    $nav.BackColor = [System.Drawing.Color]::FromArgb(29,24,30)
    $nav.Add_Click({ param($sender,$eventArgs) Select-Job $sender.Tag })
    $window.Controls.Add($nav)

    $card = [System.Windows.Forms.Button]::new()
    $card.Text = $jobs[$index]
    $card.Tag = $index
    $card.SetBounds((194 + ($index % 4) * 255),(207 + [math]::Floor($index / 4) * 155),243,144)
    $card.TextAlign = 'BottomLeft'
    $card.Padding = [System.Windows.Forms.Padding]::new(9,0,0,5)
    $card.FlatStyle = 'Flat'
    $card.FlatAppearance.BorderColor = $accent
    $card.BackColor = [System.Drawing.Color]::FromArgb(26,24,30)
    $card.Image = Get-Art ($index + 1)
    $images.Add($card.Image)
    $card.ImageAlign = 'TopCenter'
    $card.Add_Click({ param($sender,$eventArgs) Select-Job $sender.Tag })
    $window.Controls.Add($card)
}
try { [void]$window.ShowDialog() }
finally {
    $window.Dispose()
    foreach ($picture in $images) { $picture.Dispose() }
}
